<script>
document.querySelectorAll('.js-image-form').forEach(form=>{const input=form.querySelector('.js-conference-images'),preview=form.querySelector('.js-preview');input?.addEventListener('change',async()=>{const converted=[];preview.innerHTML='';for(const file of input.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type))continue;const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const scale=Math.min(1,2560/Math.max(bitmap.width,bitmap.height));const width=Math.round(bitmap.width*scale),height=Math.round(bitmap.height*scale),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(bitmap,0,0,width,height);bitmap.close();let quality=.89,blob=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));while(blob.size>8*1024*1024&&quality>.82){quality-=.02;blob=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));}const webp=new File([blob],file.name.replace(/\.[^.]+$/,'.webp'),{type:'image/webp',lastModified:file.lastModified});converted.push(webp);const item=document.createElement('div');item.className='fc-preview-item';item.innerHTML=`<img alt="Prévia da folha"><small>${width} × ${height}px · ${(blob.size/1024/1024).toFixed(2)} MB</small>`;item.querySelector('img').src=URL.createObjectURL(blob);preview.appendChild(item);}const transfer=new DataTransfer();converted.forEach(file=>transfer.items.add(file));input.files=transfer.files;});});
</script>
